fn put64(out:[*]u8,pos:*usize,x:i64)void{const bits:u64=@bitCast(x);for(0..8)|j|{out[pos.*]=@truncate(bits>>(8*j));pos.*+=1;}}
export fn stack_tracking_min_max(input:?[*]const i64,length:usize,output:?[*]u8,capacity:usize)i64{if(input==null or length<2 or length>130)return -1;const p=input.?;const max_size=p[0];const op_count=p[1];if(max_size<0 or max_size>64 or op_count<0 or op_count>64)return -1;var cursor:usize=2;for(0..@intCast(op_count)) |_|{if(cursor>=length)return -1;const op=p[cursor];cursor+=1;if(op==1){if(cursor>=length or p[cursor]< -2147483648 or p[cursor]>2147483647)return -1;cursor+=1;}else if(op<2 or op>5)return -1;}if(cursor!=length)return -1;var vals:[64]i64=@splat(0);var mins:[64]i64=@splat(0);var maxs:[64]i64=@splat(0);var records:[64][3]i64=@splat(@splat(0));var top:usize=0;var rc:usize=0;cursor=2;for(0..@intCast(op_count)) |_|{const op=p[cursor];cursor+=1;var tag:i64=0;var result:i64=0;if(op==1){const x=p[cursor];cursor+=1;if(top==@as(usize,@intCast(max_size))){records[rc]=.{1,4,1};rc+=1;break;}vals[top]=x;mins[top]=if(top==0)x else @min(mins[top-1],x);maxs[top]=if(top==0)x else @max(maxs[top-1],x);top+=1;tag=1;result=1;}else if(op==2){if(top>0){top-=1;result=vals[top];}else tag=3;}else if(op==3){if(top>0)result=mins[top-1] else tag=3;}else if(op==4){if(top>0)result=maxs[top-1] else tag=3;}else{tag=1;result=if(top>0)1 else 0;}records[rc]=.{op,tag,result};rc+=1;}const need=rc*24;if(output==null or capacity<need)return -2;const out=output.?;var pos:usize=0;for(0..rc)|i|for(0..3)|j|put64(out,&pos,records[i][j]);return @intCast(pos);}
